const FILES=['./stadium-fx.js?v=60','./game-hud.js?v=56','./game-hud.css?v=56','./menu-polish.css?v=58','./music.js?v=56','./broadcast-dome.js?v=60.1','./venue-vision.js?v=60','./play-review.js?v=56','./match-models.js?v=56','./assets/3d/jersey.glb','./assets/3d/intercontinental.glb','./assets/career/album-scenes.webp','./career-extras.js?v=56','./career-extras-view.js?v=56','./assets/fonts/noto-display-bold-italic.woff','./assets/fonts/noto-jp-display-bold.woff','./career-life.js?v=56','./career-leagues.js?v=56','./career-development.js?v=56','./career.js?v=56','./career-view.js?v=56','./career.css?v=56','./apbc-tournament.js?v=56','./apbc-candidates.js?v=56','./assets/nations/australia.svg','./derby.js?v=56','./playoff-view.js?v=56','./results.js?v=56','./matchup-data.js?v=56','./apbc-data.js?v=56','./assets/nations/taipei.svg','./assets/nations/korea.svg','./assets/nations/japan.svg','./runner-map.js?v=56','./','./index.html','./style.css?v=56','./arcade.css?v=60','./squad.js?v=56','./assets/menu/clubhouse-v18.webp','./assets/menu/trophy.svg','./vendor/three.module.min.js','./stadium3d.js?v=60.1','./stadium-premium.js?v=57','./canvas3d.js?v=56','./ratings-data.js?v=56','./players.js?v=60','./pennant.js?v=56','./game.js?v=60','./renderer.js?v=60','./app.js?v=60.1','./audio.js?v=56','./assets/audio/credits.json','./assets/audio/bat-1.mp3','./assets/audio/bat-2.mp3','./assets/audio/mitt-1.mp3','./assets/audio/mitt-2.mp3','./assets/audio/crowd-bed.mp3','./assets/audio/crowd-cheer.mp3','./assets/audio/swish.mp3','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest','./assets/clubs/brothers.png','./assets/clubs/dragons.png','./assets/clubs/lions.png','./assets/clubs/guardians.png','./assets/clubs/monkeys.png','./assets/clubs/hawks.png'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&r.type!=='opaque'){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
